css:
:root{--nv:#0A1B25;--nv2:#12283A;--nv3:#1C3446;--or:#FD450F;--or2:#D8380C;--or3:#FF6A3D;--cream:#F6F3EE;--sand:#EDE7DD;--line:#DED7CB;--mut:#56646E;--white:#fff;--wrap:1240px;--gut:clamp(16px,3vw,32px);--hd:84px}
*,*::before,*::after{box-sizing:border-box}
html{scroll-behavior:smooth;scroll-padding-top:120px}
body{margin:0;background:var(--cream);color:var(--nv);font-family:Inter,system-ui,-apple-system,"Segoe UI",Roboto,Arial,sans-serif;font-size:17px;line-height:1.6;-webkit-font-smoothing:antialiased}
img{max-width:100%;height:auto;display:block}
a{color:inherit}
h1,h2,h3{font-family:Poppins,"Arial Black",Arial,sans-serif;line-height:1.08;margin:0;letter-spacing:-.015em}
p{margin:0 0 1em}
.wrap{max-width:var(--wrap);margin-inline:auto;padding-inline:var(--gut)}
.skip{position:fixed;left:12px;top:-90px;z-index:200;background:var(--or);color:var(--nv);padding:10px 16px;border-radius:6px;font-weight:700;text-decoration:none}
.skip:focus{top:10px}
:focus-visible{outline:3px solid var(--or);outline-offset:3px}
.ico{width:1.1em;height:1.1em;fill:currentColor;flex:none}

/* ---------- Buttons ---------- */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:10px;min-height:54px;padding:0 26px;border:0;border-radius:4px;font-family:Poppins,Arial,sans-serif;font-weight:700;font-size:1.05rem;text-decoration:none;cursor:pointer;white-space:nowrap;transition:transform .15s ease,background-color .15s ease,box-shadow .15s ease}
.btn:hover{transform:translateY(-2px)}
.btn-or{background:var(--or);color:var(--nv);box-shadow:0 10px 24px -12px rgba(253,69,15,.8)}
.btn-or:hover{background:var(--or3)}
.btn-nv{background:var(--nv);color:#fff}
.btn-nv:hover{background:var(--nv3)}

/* ---------- Header ---------- */
.hd{position:sticky;top:0;z-index:50;background:var(--cream);box-shadow:0 1px 0 var(--line)}
.hd-top{background:var(--nv);color:#fff;font-family:Poppins,Arial,sans-serif;font-weight:600;font-size:.86rem;letter-spacing:.04em}
.hd-top .wrap{display:flex;justify-content:space-between;align-items:center;min-height:40px;gap:16px}
.hd-top p{margin:0;display:flex;align-items:center;gap:10px}
.hd-top a{color:#fff;text-decoration:none}
.hd-top a:hover{color:var(--or3)}
.live{width:10px;height:10px;border-radius:50%;background:#2ECC71;box-shadow:0 0 0 0 rgba(46,204,113,.7);animation:live 2s ease-out infinite}
@keyframes live{0%{box-shadow:0 0 0 0 rgba(46,204,113,.7)}80%,100%{box-shadow:0 0 0 9px rgba(46,204,113,0)}}
.hd-sep{width:1px;height:16px;background:rgba(255,255,255,.5)}
.hd-main{display:flex;align-items:center;gap:24px;height:var(--hd)}
.brand{flex:none}
.brand img{height:54px;width:auto}
.navcheck{position:absolute;opacity:0;pointer-events:none}
.burger{display:none}
.nav{flex:1;display:flex;justify-content:flex-end}
.nav-list{display:flex;gap:6px;list-style:none;margin:0;padding:0}
.nav-item{position:relative}
.nav-link{display:flex;align-items:center;height:var(--hd);padding:0 14px;font-family:Poppins,Arial,sans-serif;font-weight:600;font-size:1rem;text-decoration:none;color:var(--nv);border-bottom:3px solid transparent}
.nav-link:hover,.has-sub:hover>.nav-link,.has-sub:focus-within>.nav-link{border-bottom-color:var(--or)}
.has-sub>.nav-link::after{content:"";width:7px;height:7px;margin:-4px 0 0 9px;border-right:2px solid currentColor;border-bottom:2px solid currentColor;transform:rotate(45deg)}
.sub{display:none;position:absolute;top:100%;left:-10px;min-width:520px;background:#fff;border-top:4px solid var(--or);box-shadow:0 30px 50px -24px rgba(10,27,37,.45);padding:22px 26px;grid-template-columns:1fr 1fr;gap:4px 28px;list-style:none;margin:0}
.sub-areas{min-width:420px}
.has-sub:hover>.sub,.has-sub:focus-within>.sub{display:grid}
.sub a{display:block;padding:7px 0;text-decoration:none;font-weight:500;color:var(--nv);border-bottom:1px solid #EEE9E1}
.sub a:hover{color:var(--or2)}
.sub .sub-all{grid-column:1/-1;border:0;margin-top:8px;font-weight:700;color:var(--or2)}
.hd-cta{flex:none}
.hd-cta .btn{min-height:50px;font-size:1.12rem;padding:0 22px}

/* ---------- Hero ---------- */
.hero{position:relative;background:var(--nv);overflow:hidden;min-height:600px;display:flex;align-items:stretch}
.hero-photo{position:absolute;top:0;bottom:0;right:0;left:34%;margin:0}
.hero-photo img{width:100%;height:100%;object-fit:cover;object-position:left center}
.hero-shape{position:absolute;top:0;bottom:0;left:-30%;width:77%;background:var(--nv);transform:skewX(-13deg);transform-origin:bottom left;z-index:1}
.hero-slash{position:absolute;bottom:0;left:47%;width:30px;height:46%;background:var(--or);transform:skewX(-13deg);transform-origin:bottom left;z-index:2}
.hero-pipes{position:absolute;left:0;bottom:0;width:48%;height:96px;z-index:2;pointer-events:none}
.hero-in{position:relative;z-index:3;width:100%;display:grid;grid-template-columns:minmax(0,1fr) 360px;align-items:center;gap:40px;padding-block:56px 120px}
.hero-copy{max-width:470px;color:#fff}
.eyebrow{display:inline-block;font-family:Poppins,Arial,sans-serif;font-weight:600;font-size:.92rem;letter-spacing:.14em;text-transform:uppercase;margin:0 0 22px;padding-bottom:14px;position:relative}
.eyebrow::after{content:"";position:absolute;left:0;bottom:0;width:64px;height:4px;background:var(--or)}
.hero h1{font-size:clamp(2.6rem,5.2vw,4.4rem);font-weight:800;line-height:1;margin-bottom:20px;animation:rise .8s .1s ease-out both}
.hero-sub{font-size:1.15rem;font-weight:600;margin-bottom:10px;animation:rise .8s .2s ease-out both}
.hero-lead{color:#C9D4DB;font-size:1.02rem;margin-bottom:28px;animation:rise .8s .3s ease-out both}
.hero-cta{display:flex;flex-wrap:wrap;align-items:center;gap:14px 26px;animation:rise .8s .4s ease-out both}
.hero-cta .btn{font-size:1.25rem;min-height:60px;padding-inline:30px}
.textlink{color:#fff;font-weight:600;text-decoration:underline;text-decoration-thickness:2px;text-underline-offset:6px}
.textlink:hover{color:var(--or3)}
.hero-ticks{display:flex;flex-wrap:wrap;gap:8px 22px;list-style:none;margin:30px 0 0;padding:0;font-size:.95rem;font-weight:600;color:#DCE4E9;animation:rise .8s .5s ease-out both}
.hero-ticks li{display:flex;align-items:center;gap:8px}
.hero-ticks li::before{content:"";width:8px;height:14px;margin-top:-4px;border-right:3px solid var(--or);border-bottom:3px solid var(--or);transform:rotate(45deg)}
@keyframes rise{from{opacity:0;transform:translateY(18px)}to{opacity:1;transform:none}}

.cb{background:#fff;border-radius:4px;padding:26px 24px 24px;box-shadow:0 30px 60px -24px rgba(0,0,0,.55);position:relative;animation:rise .8s .35s ease-out both}
.cb::before{content:"";position:absolute;left:24px;right:24px;top:0;height:4px;background:var(--or)}
.cb h2{font-size:1.6rem;font-weight:700;margin:6px 0 16px}
.cb label{display:block;font-weight:700;font-size:.92rem;margin:0 0 5px}
.cb input,.cb select{width:100%;min-height:46px;border:1.5px solid #B9C2C8;border-radius:4px;padding:10px 12px;font:inherit;font-size:1rem;margin-bottom:14px;background:#fff;color:var(--nv)}
.cb input:focus-visible,.cb select:focus-visible{outline:3px solid var(--or);outline-offset:1px}
.cb .btn{width:100%;margin-top:4px;font-size:1.1rem}
.cb-note{margin:12px 0 0;font-size:.86rem;color:var(--mut);text-align:center}

/* ---------- Pipe (CSS) ---------- */
.pipe{position:relative;height:18px;border-radius:9px;background:linear-gradient(180deg,#2B4558 0%,#0F2433 38%,#0A1B25 62%,#050F16 100%);box-shadow:0 6px 12px -6px rgba(10,27,37,.5)}
.pipe::before{content:"";position:absolute;left:8px;right:8px;top:3px;height:3px;border-radius:2px;background:rgba(255,255,255,.18)}
.pipe::after{content:"";position:absolute;left:0;right:0;top:6px;height:6px;border-radius:3px;background-image:linear-gradient(90deg,rgba(253,69,15,0) 0,rgba(253,69,15,.95) 40px,rgba(255,170,120,1) 46px,rgba(253,69,15,0) 90px);background-size:340px 100%;background-repeat:repeat-x;animation:flow 3.2s linear infinite;opacity:.95}
@keyframes flow{from{background-position:0 0}to{background-position:340px 0}}
.collar{position:absolute;top:-5px;width:24px;height:28px;margin-left:-12px;border-radius:3px;background:linear-gradient(90deg,var(--or) 0 32%,var(--or2) 32% 68%,var(--or) 68% 100%);box-shadow:0 4px 8px -3px rgba(10,27,37,.45);z-index:1}
.collar.slate{background:linear-gradient(90deg,#1C3446 0 32%,#2B4558 32% 68%,#1C3446 68% 100%)}

/* ---------- Stats ---------- */
.stats{padding:44px 0 0}
.stats-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:0}
.stat{padding:6px 28px 30px;border-left:1px solid var(--line)}
.stat:first-child{border-left:0;padding-left:0}
.stat::before{content:"";display:block;width:58px;height:4px;background:var(--or);margin-bottom:16px}
.stat b{display:block;white-space:nowrap;font-family:Poppins,Arial,sans-serif;font-weight:800;font-size:clamp(1.9rem,3.1vw,2.75rem);line-height:1;letter-spacing:-.02em}
.stat span{display:block;margin-top:10px;font-family:Poppins,Arial,sans-serif;font-weight:600;font-size:.8rem;letter-spacing:.24em;text-transform:uppercase}
.stats .pipe{margin-top:8px}

/* ---------- Services ---------- */
.services{padding:64px 0 76px}
.svc-grid{display:grid;grid-template-columns:minmax(0,4fr) minmax(0,8fr);gap:56px;align-items:start}
.svc-head h2{font-size:clamp(2.4rem,4.2vw,3.6rem);font-weight:800;line-height:.98;margin-bottom:14px}
.svc-head .sub-l{font-size:1.15rem;font-weight:500;margin-bottom:16px}
.svc-head p{color:var(--mut)}
.svc-art{margin-top:26px;width:100%;max-width:360px}
.svc-list{display:grid;grid-template-columns:1fr 1fr;column-gap:52px;list-style:none;margin:0;padding:0 0 0 52px;border-left:1px solid var(--line)}
.svc-list a{position:relative;display:flex;justify-content:space-between;align-items:center;gap:14px;padding:17px 0;font-family:Poppins,Arial,sans-serif;font-weight:700;font-size:1.14rem;text-decoration:none;border-bottom:1.5px solid #CFC7B9}
.svc-list a::after{content:"";position:absolute;left:0;bottom:-1.5px;height:3px;width:0;background:var(--or);transition:width .45s ease}
.svc-list a:hover::after,.svc-list a:focus-visible::after{width:100%}
.svc-list a:hover{color:var(--or2)}
.svc-list svg{width:22px;height:22px;flex:none;transition:transform .2s ease}
.svc-list a:hover svg{transform:translateX(5px)}

/* SVG pipe animation helpers */
.p-body{fill:none;stroke:#0A1B25;stroke-linecap:round;stroke-linejoin:round}
.p-hi{fill:none;stroke:rgba(255,255,255,.16);stroke-linecap:round;stroke-linejoin:round}
.p-flow{fill:none;stroke:var(--or);stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:14 46;animation:dash 1.6s linear infinite}
.p-flow.slow{animation-duration:2.6s}
.p-flow.water{stroke:#7CC7E8;stroke-dasharray:10 34}
@keyframes dash{to{stroke-dashoffset:-60}}
.spin{transform-box:fill-box;transform-origin:center;animation:spin 6s linear infinite}
@keyframes spin{to{transform:rotate(360deg)}}
.needle{transform-box:view-box;animation:needle 3.4s ease-in-out infinite}
@keyframes needle{0%,100%{transform:rotate(-38deg)}40%{transform:rotate(30deg)}55%{transform:rotate(22deg)}70%{transform:rotate(34deg)}}
.drop{animation:drop 1.9s cubic-bezier(.55,0,1,.45) infinite}
@keyframes drop{0%{transform:translateY(0) scale(.2);opacity:0}25%{transform:translateY(0) scale(1);opacity:1}70%{opacity:1}100%{transform:translateY(46px) scale(1,1.25);opacity:0}}
.ripple{transform-box:fill-box;transform-origin:center;animation:ripple 1.9s ease-out infinite}
@keyframes ripple{0%,60%{transform:scale(.2);opacity:0}70%{opacity:.9}100%{transform:scale(1.6);opacity:0}}

/* ---------- Sectors ---------- */
.sectors{background:#fff;padding:76px 0}
.sec-head{display:flex;justify-content:space-between;align-items:end;gap:30px;margin-bottom:34px}
.sec-head h2{font-size:clamp(2rem,3.4vw,2.9rem);font-weight:800;max-width:620px}
.sec-head p{max-width:440px;color:var(--mut);margin:0}
.cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:28px}
.card{display:flex;flex-direction:column;background:var(--cream);border-radius:4px;overflow:hidden}
.card .pipe{height:12px;border-radius:0}
.card .pipe::after{top:3px;height:6px;animation-duration:2.6s}
.card .pipe::before{display:none}
.card img{width:100%;aspect-ratio:10/7;object-fit:cover}
.card-b{padding:24px 24px 28px;display:flex;flex-direction:column;flex:1}
.card h3{font-size:1.45rem;font-weight:800;margin-bottom:10px}
.card p{color:var(--mut);font-size:1rem}
.more{margin-top:auto;align-self:flex-start;display:inline-flex;align-items:center;gap:8px;font-family:Poppins,Arial,sans-serif;font-weight:700;text-decoration:underline;text-decoration-color:var(--or);text-decoration-thickness:3px;text-underline-offset:7px}
.more:hover{color:var(--or2)}

/* ---------- Local ---------- */
.local{padding:80px 0}
.local-grid{display:grid;grid-template-columns:minmax(0,5fr) minmax(0,7fr);gap:56px;align-items:center}
.local-media{position:relative}
.local-media img{border-radius:4px;width:100%}
.local-badge{position:absolute;right:-18px;bottom:28px;background:var(--or);color:var(--nv);padding:18px 22px;border-radius:4px;font-family:Poppins,Arial,sans-serif;box-shadow:0 20px 34px -18px rgba(10,27,37,.6)}
.local-badge b{display:block;font-size:2.3rem;font-weight:800;line-height:1}
.local-badge span{font-weight:600;font-size:.9rem}
.local h2{font-size:clamp(2rem,3.4vw,2.9rem);font-weight:800;margin-bottom:16px}
.local .lead{font-size:1.1rem;color:var(--mut);max-width:60ch}
.points{display:grid;grid-template-columns:1fr 1fr;gap:6px 34px;margin-top:22px}
.point{border-top:1.5px solid #CFC7B9;padding:18px 0 4px}
.point h3{font-size:1.12rem;font-weight:700;margin-bottom:6px}
.point p{color:var(--mut);font-size:.98rem}
.inl{color:var(--or2);font-weight:600;text-decoration:underline;text-decoration-thickness:1.5px;text-underline-offset:3px}
.inl:hover{color:var(--nv)}

/* ---------- Map ---------- */
.areas{position:relative;background:var(--nv);color:#fff;overflow:hidden}
.areas-grid{display:grid;grid-template-columns:minmax(0,5fr) minmax(0,7fr);align-items:stretch;min-height:560px}
.areas-copy{position:relative;z-index:2;padding:70px 40px 220px 0}
.areas h2{font-size:clamp(2.3rem,4vw,3.4rem);font-weight:800;line-height:1;margin-bottom:12px}
.areas .sub-l{font-size:1.2rem;font-weight:500;color:#DCE4E9;margin-bottom:24px}
.areas p.txt{color:#C2CED6;max-width:44ch}
.legend{display:flex;align-items:center;gap:10px;margin:22px 0 0;font-size:.92rem;color:#DCE4E9}
.legend i{width:20px;height:20px;border-radius:50%;background:var(--or);box-shadow:0 0 0 4px rgba(253,69,15,.3),0 0 0 7px rgba(253,69,15,.12)}
.chips{display:flex;flex-wrap:wrap;gap:8px;list-style:none;margin:26px 0 0;padding:0;max-width:460px}
.chips a{display:inline-block;padding:7px 13px;border:1.5px solid #2E4A5E;border-radius:40px;font-size:.88rem;font-weight:600;text-decoration:none;color:#E4EBEF}
.chips a:hover{border-color:var(--or);color:#fff;background:rgba(253,69,15,.15)}
.map{position:relative;margin:0 calc(-1 * max(var(--gut),(100vw - var(--wrap))/2 + var(--gut))) 0 0}
.map svg{display:block;width:100%;height:100%;min-height:600px}
.map .lbl rect{fill:#fff;stroke:#0A1B25;stroke-width:1.5}
.map .lbl text{font-family:Poppins,Arial,sans-serif;font-weight:700;font-size:13px;fill:#0A1B25}
.pin-pulse{transform-box:fill-box;transform-origin:center;animation:pulse 2.4s ease-out infinite}
@keyframes pulse{0%{transform:scale(.6);opacity:.8}100%{transform:scale(2.4);opacity:0}}
.terrace{position:absolute;left:max(var(--gut),calc((100vw - var(--wrap))/2 + var(--gut)));bottom:0;width:min(470px,42vw);z-index:1;pointer-events:none}

/* ---------- FAQ ---------- */
.faq{padding:80px 0}
.faq-grid{display:grid;grid-template-columns:minmax(0,4fr) minmax(0,8fr);gap:56px;align-items:start}
.faq h2{font-size:clamp(2rem,3.4vw,2.9rem);font-weight:800;margin-bottom:14px}
.faq-intro p{color:var(--mut)}
.qa{border-top:1.5px solid #CFC7B9}
.qa:last-child{border-bottom:1.5px solid #CFC7B9}
.qa summary{list-style:none;cursor:pointer;display:flex;justify-content:space-between;align-items:center;gap:18px;padding:20px 0;font-family:Poppins,Arial,sans-serif;font-weight:700;font-size:1.15rem}
.qa summary::-webkit-details-marker{display:none}
.qa summary::after{content:"";flex:none;width:30px;height:30px;border-radius:50%;background:var(--nv);transition:transform .25s ease,background-color .25s ease}
.qa[open] summary::after{transform:rotate(45deg);background-color:var(--or)}
.qa .ans{padding:0 50px 22px 0;color:var(--mut)}
.qa .ans p{margin:0}

/* ---------- CTA band ---------- */
.cta{position:relative;background:var(--or);overflow:hidden}
.cta::after{content:"";position:absolute;top:0;bottom:0;right:4%;width:34px;background:var(--nv);transform:skewX(-20deg)}
.cta-in{position:relative;z-index:1;display:flex;align-items:center;justify-content:space-between;gap:28px;padding-block:38px;padding-right:120px}
.cta h2{font-size:clamp(2rem,4vw,3.3rem);font-weight:800;line-height:1}
.cta p{margin:6px 0 0;font-size:1.25rem;font-weight:500}
.cta-tap{width:110px;flex:none}
.cta .btn{min-height:64px;font-size:1.45rem;padding-inline:34px}

/* ---------- Footer ---------- */
.ft{background:var(--nv);color:#C9D4DB;position:relative}
.ft>.pipe{border-radius:0;height:16px}
.ft>.pipe::before{display:none}
.ft-grid{display:grid;grid-template-columns:1.4fr 1fr 1fr 1.1fr;gap:40px;padding-block:58px 40px}
.ft-brand img{height:62px;width:auto;margin-bottom:18px}
.ft-brand p{font-size:.96rem;max-width:34ch}
.ft h2{font-family:Poppins,Arial,sans-serif;font-size:1.1rem;font-weight:700;color:#fff;margin:0 0 14px}
.ft ul{list-style:none;margin:0;padding:0;display:grid;gap:9px}
.ft ul a{text-decoration:none;font-size:.97rem}
.ft ul a:hover{color:#fff;text-decoration:underline;text-decoration-color:var(--or)}
.ft-call{display:block;font-family:Poppins,Arial,sans-serif;font-weight:800;font-size:1.9rem;color:var(--or);text-decoration:none;line-height:1.1;margin-bottom:6px}
.ft-call:hover{color:var(--or3)}
.ft-open{color:#fff;font-weight:600;margin-bottom:14px}
.ft-base{border-top:1px solid #23394A}
.ft-base .wrap{display:flex;flex-wrap:wrap;justify-content:space-between;gap:10px 24px;padding-block:20px;font-size:.88rem}
.ft-base p{margin:0}
.ft-base a{color:#C9D4DB}
.credit{display:inline-flex;align-items:center;gap:8px}
.credit i{width:8px;height:8px;border-radius:50%;background:var(--or)}

/* ---------- Mobile call bar ---------- */
.callbar{display:none}

/* ---------- Responsive ---------- */
@media (max-width:1180px){
  .nav-link{padding:0 10px;font-size:.95rem}
  .hd-cta .btn{font-size:1rem;padding:0 16px}
  .hero-in{grid-template-columns:minmax(0,1fr) 330px;gap:28px}
  .svc-list{padding-left:36px;column-gap:36px}
}
@media (max-width:980px){
  :root{--hd:70px}
  .brand img{height:44px}
  .burger{display:inline-flex;align-items:center;gap:9px;min-height:44px;padding:0 13px;border-radius:4px;box-shadow:inset 0 0 0 2px var(--nv);font-family:Poppins,Arial,sans-serif;font-weight:700;cursor:pointer;margin-left:auto;order:3}
  .bars{width:18px;height:12px;border-top:2px solid currentColor;border-bottom:2px solid currentColor;position:relative}
  .bars::after{content:"";position:absolute;left:0;right:0;top:3px;border-top:2px solid currentColor}
  .navcheck:checked+.burger{background:var(--nv);color:#fff}
  .navcheck:focus-visible+.burger{outline:3px solid var(--or);outline-offset:3px}
  .hd-cta{order:2;margin-left:auto}
  .hd-cta .btn span{display:none}
  .hd-cta .btn{min-height:44px;padding:0 14px}
  .nav{display:none;position:absolute;left:0;right:0;top:100%;background:#fff;border-bottom:4px solid var(--or);box-shadow:0 30px 50px -30px rgba(10,27,37,.5);max-height:calc(100vh - 120px);overflow:auto;padding:4px var(--gut) 20px}
  .navcheck:checked~.nav{display:block}
  .nav-list{display:block}
