/* ---------- v2 additions ---------- */
.hero h1 .h1-a{display:block}
.hero h1 .h1-b{display:block;font-size:.42em;line-height:1.15;font-weight:700;color:#FFB59B;margin-top:14px;letter-spacing:0}
.cb-title{font-family:Poppins,Arial,sans-serif;font-size:1.6rem;font-weight:700;line-height:1.1;margin:6px 0 16px}

/* in-body content links: visible, hoverable (M9) */
main p a.il,main li a.il,main td a.il,.ans a.il,main .inl{color:#A82C08;font-weight:600;text-decoration:underline;text-decoration-thickness:1.5px;text-underline-offset:3px}
main p a.il:hover,main li a.il:hover,.ans a.il:hover{color:var(--nv);text-decoration-thickness:2.5px}
/* links on dark sections: light orange at rest, white on hover (never the background colour) */
.trust a.il,.areas a.il,.svc3d a.il,.cta a.il,.hero a.il{color:#FF8A5C;text-decoration-color:#FF8A5C}
.trust a.il:hover,.areas a.il:hover,.svc3d a.il:hover,.cta a.il:hover,.hero a.il:hover,
.trust a.il:focus-visible,.areas a.il:focus-visible,.svc3d a.il:focus-visible{color:#fff;text-decoration-color:#fff}

/* FAQ toggle without any image data */
.qa summary::after{background:linear-gradient(#fff,#fff) center/14px 2px no-repeat,linear-gradient(#fff,#fff) center/2px 14px no-repeat,var(--nv)}
.qa[open] summary::after{background:linear-gradient(#fff,#fff) center/14px 2px no-repeat,linear-gradient(#fff,#fff) center/2px 14px no-repeat,var(--or)}

/* ---------- 3D service tiles ---------- */
.svc3d{position:relative;background:radial-gradient(1100px 520px at 12% -8%,rgba(253,69,15,.22),transparent 60%),radial-gradient(900px 600px at 105% 110%,rgba(46,155,214,.14),transparent 60%),#07141C;color:#fff;padding:96px 0 104px;overflow:hidden}
.svc3d::before{content:"";position:absolute;inset:0;background-image:linear-gradient(rgba(255,255,255,.035) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.035) 1px,transparent 1px);background-size:56px 56px;mask-image:radial-gradient(ellipse at center,#000 30%,transparent 80%);-webkit-mask-image:radial-gradient(ellipse at center,#000 30%,transparent 80%);pointer-events:none}
.svc3d .wrap{position:relative}
.svc3d-head{display:grid;grid-template-columns:minmax(0,7fr) minmax(0,5fr);gap:40px;align-items:end;margin-bottom:46px}
.kicker{display:inline-flex;align-items:center;gap:10px;font-family:Poppins,Arial,sans-serif;font-weight:600;font-size:.86rem;letter-spacing:.18em;text-transform:uppercase;color:#FF8A5C;margin:0 0 16px}
.kicker::before{content:"";width:34px;height:3px;background:var(--or)}
.svc3d h2{font-size:clamp(2.3rem,4.6vw,4rem);font-weight:800;line-height:.98;margin:0}
.svc3d h2 em{font-style:normal;color:var(--or)}
.svc3d-lead{color:#C2CED6;font-size:1.08rem;margin:0}
.svc3d-hint{display:flex;align-items:center;gap:10px;margin:14px 0 0;color:#8FA3B0;font-size:.9rem;font-weight:600}
.svc3d-hint i{width:26px;height:26px;border-radius:50%;border:2px solid #8FA3B0;position:relative;animation:hint 2.2s ease-in-out infinite}
.svc3d-hint i::after{content:"";position:absolute;left:50%;top:50%;width:6px;height:6px;margin:-3px 0 0 -3px;border-radius:50%;background:var(--or)}
@keyframes hint{0%,100%{transform:translate(0,0)}50%{transform:translate(8px,-4px)}}

.tiles{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));grid-auto-rows:minmax(214px,auto);grid-auto-flow:dense;gap:20px;list-style:none;margin:0;padding:0;perspective:1600px}
.tile-li{display:flex}
.tile-li.xl{grid-column:span 2;grid-row:span 2}
.tile-li.wide{grid-column:span 2}
.tile{--rx:0deg;--ry:0deg;--mx:50%;--my:0%;position:relative;flex:1;display:flex;flex-direction:column;padding:24px 24px 22px;border-radius:20px;transform-style:preserve-3d;transform:rotateX(var(--rx)) rotateY(var(--ry));transition:transform .5s cubic-bezier(.2,.8,.2,1),box-shadow .4s ease;box-shadow:0 30px 60px -34px rgba(0,0,0,.9),0 0 0 1px rgba(255,255,255,.07)}
.tile-bg{position:absolute;inset:0;border-radius:20px;overflow:hidden;background:linear-gradient(155deg,#18344A 0%,#0E2433 48%,#09161F 100%);transform:translateZ(-2px)}
.tile-bg::before{content:"";position:absolute;inset:0;border-radius:20px;padding:1px;background:linear-gradient(140deg,rgba(255,255,255,.22),rgba(255,255,255,0) 40%,rgba(253,69,15,0) 60%,rgba(253,69,15,.55));-webkit-mask:linear-gradient(#000 0 0) content-box,linear-gradient(#000 0 0);-webkit-mask-composite:xor;mask-composite:exclude;opacity:.6;transition:opacity .4s}
.tile-bg::after{content:"";position:absolute;inset:0;background:radial-gradient(circle at var(--mx) var(--my),rgba(255,255,255,.22),rgba(255,255,255,0) 42%);opacity:0;transition:opacity .4s}
.water{position:absolute;left:0;right:0;bottom:0;height:100%;transform:translateY(92%);transition:transform 1.1s cubic-bezier(.2,.8,.2,1);background:linear-gradient(180deg,rgba(46,155,214,.38),rgba(20,96,140,.55))}
.water::before,.water::after{content:"";position:absolute;left:0;right:0;top:-14px;height:16px;background:radial-gradient(14px 12px at 14px 16px,rgba(46,155,214,.38) 98%,transparent 100%) repeat-x;background-size:28px 16px;animation:wave 2.2s linear infinite}
.water::after{top:-10px;opacity:.6;background-size:36px 16px;animation-duration:3.4s;animation-direction:reverse}
@keyframes wave{to{background-position:56px 0}}
.bubbles{position:absolute;inset:0;opacity:0;transition:opacity .6s}
.bubbles i{position:absolute;bottom:-10px;width:7px;height:7px;border-radius:50%;border:1.5px solid rgba(255,255,255,.55);animation:bub 3s linear infinite}
.bubbles i:nth-child(1){left:18%;animation-delay:.2s}.bubbles i:nth-child(2){left:46%;width:5px;height:5px;animation-delay:1.1s}.bubbles i:nth-child(3){left:72%;animation-delay:1.9s}.bubbles i:nth-child(4){left:86%;width:4px;height:4px;animation-delay:.7s}
@keyframes bub{from{transform:translateY(0);opacity:0}15%{opacity:1}to{transform:translateY(-190px);opacity:0}}
.tile-top{position:relative;display:flex;justify-content:space-between;align-items:flex-start;transform:translateZ(30px)}
.tile-no{font-family:Poppins,Arial,sans-serif;font-weight:700;font-size:.8rem;letter-spacing:.12em;color:#7F95A3}
.tile-ico{position:relative;width:62px;height:62px;border-radius:16px;display:grid;place-items:center;background:linear-gradient(145deg,#22445C,#11283A);box-shadow:inset 0 1px 0 rgba(255,255,255,.12),0 14px 24px -12px rgba(0,0,0,.9);transform:translateZ(60px);transition:transform .5s cubic-bezier(.2,.8,.2,1),background .4s}
.tile-ico svg{width:38px;height:38px;fill:none;stroke:#E8EEF2;stroke-width:2.4;stroke-linecap:round;stroke-linejoin:round;overflow:visible}
.tile-ico .o{stroke:var(--or)}
.tile-ico .w{stroke:#5CC0EE}
.tile-ico .fill.o{fill:var(--or)}
.tile-ico .fill.w{fill:#5CC0EE}
.tile-body{margin-top:auto;padding-top:26px}
.tile h3{position:relative;z-index:3;font-size:1.24rem;font-weight:700;line-height:1.2;margin:0 0 8px;color:#fff}
.tile-link{color:inherit;text-decoration:none}
.tile-link::after{content:"";position:absolute;inset:0;z-index:4;border-radius:20px}
.tile-top,.tile p,.tile-go{pointer-events:none}
.tile p{transform:translateZ(30px)}
.tile h3{text-shadow:0 2px 12px rgba(0,0,0,.5)}
.tile{isolation:isolate}
.tile-link:focus-visible{outline:none}
.tile:focus-within{box-shadow:0 0 0 3px var(--or),0 30px 60px -30px rgba(253,69,15,.55)}
.tile p{margin:0;font-size:.95rem;line-height:1.5;color:#B4C3CD}
.tile-go{position:absolute;right:20px;bottom:20px;width:40px;height:40px;border-radius:50%;display:grid;place-items:center;background:rgba(255,255,255,.08);transform:translateZ(50px);transition:background .3s,transform .5s cubic-bezier(.2,.8,.2,1)}
.tile-go svg{width:18px;height:18px;fill:#fff;transition:transform .3s}
.tile-body{padding-right:48px}
.tile-call{position:relative;z-index:6;display:inline-flex;align-items:center;gap:8px;margin-top:16px;padding:10px 16px;border-radius:40px;background:var(--or);color:var(--nv);font-family:Poppins,Arial,sans-serif;font-weight:700;font-size:1rem;text-decoration:none;transform:translateZ(20px)}
.tile-call:hover{background:var(--or3)}
.tile-li.xl .tile{padding:32px}
.tile-li.xl .tile-ico{width:104px;height:104px;border-radius:26px}
.tile-li.xl .tile-ico svg{width:64px;height:64px}
.tile-li.xl .tile-ico::before,.tile-li.xl .tile-ico::after{content:"";position:absolute;inset:-10px;border-radius:32px;border:2px solid rgba(253,69,15,.55);animation:ring 2.4s ease-out infinite}
.tile-li.xl .tile-ico::after{animation-delay:1.2s}
@keyframes ring{from{transform:scale(.9);opacity:.9}to{transform:scale(1.35);opacity:0}}
.tile-li.xl h3{font-size:clamp(1.8rem,2.6vw,2.4rem);font-weight:800}
.tile-li.xl p{font-size:1.06rem;max-width:44ch}
.tile-li.xl .tile-bg{background:radial-gradient(500px 300px at 85% 0%,rgba(253,69,15,.35),transparent 60%),linear-gradient(155deg,#1B3A50 0%,#0E2433 50%,#09161F 100%)}

/* hover and focus: lift, tilt, fill with water */
.tile:hover,.tile:focus-within{box-shadow:0 46px 80px -34px rgba(0,0,0,.95),0 0 0 1px rgba(253,69,15,.55),0 0 46px -12px rgba(253,69,15,.45)}
.tile:hover:not(.is-tilt){transform:rotateX(7deg) rotateY(-9deg) translateY(-6px)}
.tile.is-tilt{transition:transform .12s linear,box-shadow .4s ease;transform:rotateX(var(--rx)) rotateY(var(--ry)) translateY(-6px)}
.tile:hover .water,.tile:focus-within .water{transform:translateY(58%)}
.tile:hover .bubbles,.tile:focus-within .bubbles{opacity:1}
.tile:hover .tile-bg::after{opacity:1}
.tile:hover .tile-bg::before{opacity:1}
.tile:hover .tile-ico,.tile:focus-within .tile-ico{transform:translateZ(90px) scale(1.08);background:linear-gradient(145deg,#FD450F,#B9300A)}
.tile:hover .tile-ico .o,.tile:focus-within .tile-ico .o{stroke:#fff}
.tile:hover .tile-ico .fill.o{fill:#fff}
.tile:hover .tile-go,.tile:focus-within .tile-go{background:var(--or);transform:translateZ(70px)}
.tile:hover .tile-go svg{transform:translateX(3px)}
/* icon motion while hovered */
.tile:hover .a-spin{animation:spin 2.4s linear infinite;transform-box:fill-box;transform-origin:center}
.tile:hover .a-drip{animation:drip 1.3s ease-in infinite}
.tile:hover .a-flicker{animation:flicker .5s ease-in-out infinite alternate;transform-box:fill-box;transform-origin:50% 100%}
.tile:hover .a-blink{animation:blink .8s steps(2) infinite}
.tile:hover .a-slide{animation:slide 1.6s ease-in-out infinite}
.tile:hover .a-rain{animation:rain .7s linear infinite}
.tile-li.xl .a-blink{animation:blink 1.1s steps(2) infinite}
@keyframes drip{0%{transform:translateY(-4px);opacity:0}30%{opacity:1}100%{transform:translateY(8px);opacity:0}}
@keyframes flicker{from{transform:scaleY(.9) skewX(-3deg)}to{transform:scaleY(1.08) skewX(3deg)}}
@keyframes blink{50%{opacity:.25}}
@keyframes slide{0%,100%{transform:translateX(0)}50%{transform:translateX(18px)}}
@keyframes rain{from{transform:translateY(-3px);opacity:.2}50%{opacity:1}to{transform:translateY(4px);opacity:.2}}

/* ---------- Decision table ---------- */
.decide{padding:84px 0;background:#fff}
.decide-head{max-width:820px;margin-bottom:28px}
.decide h2{font-size:clamp(2rem,3.4vw,2.9rem);font-weight:800;margin-bottom:14px}
.decide-head p{color:var(--mut);font-size:1.08rem}
.tbl-wrap{overflow-x:auto;border-radius:6px;box-shadow:0 0 0 1.5px #DED7CB}
.tbl{width:100%;border-collapse:collapse;min-width:640px;font-size:.98rem}
.tbl caption{text-align:left;caption-side:bottom;padding:12px 2px 0;color:var(--mut);font-size:.88rem}
.tbl th{background:var(--nv);color:#fff;text-align:left;font-family:Poppins,Arial,sans-serif;font-weight:600;padding:14px 16px}
.tbl td{padding:14px 16px;border-top:1px solid #ECE6DC;vertical-align:top}
.tbl tr:nth-child(even) td{background:#FAF8F4}
.tbl td:first-child{font-weight:600}
.tbl td:last-child{color:var(--or2);font-weight:600}

/* ---------- Trust ---------- */
.trust{padding:84px 0;background:var(--nv);color:#fff;position:relative;overflow:hidden}
.trust-grid{display:grid;grid-template-columns:minmax(0,5fr) minmax(0,7fr);gap:56px;align-items:start}
.trust h2{font-size:clamp(2rem,3.4vw,2.9rem);font-weight:800;margin-bottom:16px}
.trust p{color:#C2CED6}
.trust .facts{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:26px}
.trust .fact{border-top:3px solid var(--or);padding-top:12px}
.trust .fact b{display:block;font-family:Poppins,Arial,sans-serif;font-size:1.35rem}
.trust .fact span{color:#9FB2BF;font-size:.92rem}
.steps{list-style:none;margin:0;padding:0;display:grid;gap:14px;counter-reset:st}
.steps li{position:relative;counter-increment:st;background:#10283A;border-radius:10px;padding:20px 22px 20px 78px;color:#C2CED6}
.steps li::before{content:counter(st,decimal-leading-zero);position:absolute;left:20px;top:18px;font-family:Poppins,Arial,sans-serif;font-weight:800;font-size:1.6rem;color:var(--or)}
.steps li b{display:block;color:#fff;font-family:Poppins,Arial,sans-serif;font-size:1.1rem;margin-bottom:2px}
.steps li::after{content:"";position:absolute;left:36px;top:58px;bottom:-16px;width:3px;background:linear-gradient(var(--or),transparent)}
.steps li:last-child::after{display:none}

