.neon{display:inline-flex;align-items:center;gap:14px;padding:12px 22px 12px 18px;border:2px solid #FF6A3D;border-radius:14px;box-shadow:0 0 18px rgba(253,69,15,.55),inset 0 0 14px rgba(253,69,15,.35);animation:neonbox 6s infinite}
.neon-open{font-family:Poppins,Arial,sans-serif;font-weight:800;font-size:clamp(2rem,4.4vw,3.1rem);line-height:1;letter-spacing:.06em;color:#FFD9C9;text-shadow:0 0 6px #FF6A3D,0 0 16px #FD450F,0 0 34px #FD450F;animation:neon 6s infinite}
.neon-24{font-family:Poppins,Arial,sans-serif;font-weight:700;font-size:clamp(.95rem,1.8vw,1.2rem);letter-spacing:.22em;color:#fff;padding-left:14px;border-left:2px solid rgba(255,106,61,.6)}
.neon-dot{position:relative;width:14px;height:14px;border-radius:50%;background:#3BE38B;box-shadow:0 0 10px #3BE38B}
.neon-dot::after{content:"";position:absolute;inset:-6px;border-radius:50%;border:2px solid #3BE38B;animation:ping 1.6s ease-out infinite}
@keyframes ping{from{transform:scale(.6);opacity:1}to{transform:scale(1.6);opacity:0}}
@keyframes neon{0%,18%,22%,24%,62%,64%,100%{opacity:1;text-shadow:0 0 6px #FF6A3D,0 0 16px #FD450F,0 0 34px #FD450F}20%,23%,63%{opacity:.35;text-shadow:none}}
@keyframes neonbox{0%,18%,24%,62%,64%,100%{box-shadow:0 0 18px rgba(253,69,15,.55),inset 0 0 14px rgba(253,69,15,.35)}20%,63%{box-shadow:none}}
.cta2-clock{margin:18px 0 6px;font-size:1.02rem;color:#C9D5DC}
.cta2-clock b{color:#fff;font-variant-numeric:tabular-nums}
.cta2 h2{font-family:Poppins,Arial,sans-serif;font-weight:800;font-size:clamp(2.1rem,4.6vw,3.5rem);line-height:1.04;letter-spacing:-.02em;margin:0 0 18px;color:#fff}
.cta2-lead{font-size:1.12rem;line-height:1.65;color:#DCE4E9;max-width:34em;margin:0 0 22px}
.cta2-ticks{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:10px 22px;font-weight:600;color:#fff}
.cta2-ticks li{display:flex;align-items:center;gap:10px}
.cta2-ticks li::before{content:"";width:7px;height:13px;margin-top:-4px;border-right:3px solid var(--or);border-bottom:3px solid var(--or);transform:rotate(45deg)}
.console{background:#fff;color:var(--nv);border-radius:20px;padding:clamp(20px,2.6vw,30px);box-shadow:0 40px 80px -30px rgba(0,0,0,.8),0 0 0 6px rgba(255,255,255,.06)}
.bigcall{position:relative;display:flex;align-items:center;gap:18px;padding:18px 22px;border-radius:14px;background:linear-gradient(135deg,#FF5A22,#FD450F 55%,#D8380C);color:var(--nv);text-decoration:none;box-shadow:0 18px 34px -16px rgba(253,69,15,.9);transition:transform .15s ease,box-shadow .2s ease;animation:nudge 4s ease-in-out infinite}
.bigcall:hover{transform:translateY(-3px) scale(1.01);box-shadow:0 26px 40px -16px rgba(253,69,15,1)}
.bigcall:focus-visible{outline:3px solid var(--nv);outline-offset:3px}
@keyframes nudge{0%,86%,100%{transform:none}89%{transform:rotate(-1.2deg)}92%{transform:rotate(1.2deg)}95%{transform:rotate(-.8deg)}}
.bigcall-ico{position:relative;flex:none;width:62px;height:62px;border-radius:50%;background:var(--nv);display:grid;place-items:center}
.bigcall-ico svg{width:28px;height:28px;fill:#fff;animation:ringphone 2s ease-in-out infinite;transform-origin:50% 50%}
.bigcall-ico i{position:absolute;inset:0;border-radius:50%;border:2px solid var(--nv);animation:ring 2s ease-out infinite}
.bigcall-ico i+i{animation-delay:1s}
@keyframes ringphone{0%,50%,100%{transform:rotate(0)}5%,15%,25%{transform:rotate(-14deg)}10%,20%,30%{transform:rotate(14deg)}}
.bigcall-t{display:flex;flex-direction:column;line-height:1.05}
.bigcall-t small{font-family:Poppins,Arial,sans-serif;font-weight:700;font-size:.82rem;letter-spacing:.18em;text-transform:uppercase}
.bigcall-t b{font-family:Poppins,Arial,sans-serif;font-weight:800;font-size:clamp(1.7rem,3.2vw,2.35rem);letter-spacing:-.01em;white-space:nowrap}
.sms{width:100%;margin-top:12px;white-space:normal;text-align:center;line-height:1.25;background:#fff;color:var(--nv);border:2px solid var(--nv);font-size:1rem}
.sms svg{width:22px;height:22px}
.sms:hover{background:var(--nv);color:#fff}
.or{display:flex;align-items:center;gap:12px;margin:20px 0 14px;font-size:.85rem;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#56646E}
.or::before,.or::after{content:"";flex:1;height:1px;background:#DED7CB}
.chips{border:0;margin:0 0 14px;padding:0;display:flex;flex-wrap:wrap;gap:8px}
.chips legend{font-family:Poppins,Arial,sans-serif;font-weight:700;font-size:1rem;margin-bottom:10px;padding:0}
.chip-in{position:absolute;opacity:0;width:1px;height:1px}
.chip{display:inline-flex;align-items:center;min-height:40px;padding:0 14px;border:1.5px solid #B9C2C8;border-radius:40px;font-size:.92rem;font-weight:600;cursor:pointer;transition:background .15s,border-color .15s,color .15s,transform .15s;user-select:none}
.chip:hover{border-color:var(--nv);transform:translateY(-1px)}
.chip-in:checked+.chip{background:var(--nv);border-color:var(--nv);color:#fff}
.chip-in:checked+.chip::before{content:"";width:6px;height:11px;margin:-3px 9px 0 0;border-right:2.5px solid var(--or);border-bottom:2.5px solid var(--or);transform:rotate(45deg)}
.chip-in:focus-visible+.chip{outline:3px solid var(--or);outline-offset:2px}
.quick-row{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.quick input[type=text],.quick input[type=tel]{width:100%;min-height:50px;border:1.5px solid #B9C2C8;border-radius:8px;padding:10px 14px;font:inherit;font-size:1rem;color:var(--nv);background:#fff}
.quick input::placeholder{color:#5E6B74}
.quick input:focus-visible{outline:3px solid var(--or);outline-offset:1px}
.quick-go{width:100%;margin-top:10px;min-height:54px;font-size:1.08rem}
@media (max-width:900px){.cta2-in{grid-template-columns:1fr}.cta2::before{width:100%;right:0}}
@media (max-width:480px){.quick-row{grid-template-columns:1fr}.bigcall{padding:16px;gap:14px}.bigcall-ico{width:50px;height:50px}.bigcall-t b{font-size:1.5rem}.sms-x{display:none}.console{padding:18px}.neon{gap:10px;padding:10px 14px}.neon-24{letter-spacing:.14em;padding-left:10px}}
@media (prefers-reduced-motion:reduce){.neon,.neon-open,.neon-dot::after,.cta2::before,.bigcall,.bigcall-ico svg,.bigcall-ico i{animation:none!important}}

/* ===== quick quote drawer ===== */
.vh{position:absolute!important;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
.qq-tog{position:fixed;opacity:0;width:1px;height:1px;right:0;top:50%;pointer-events:none}
.qq-tab{position:fixed;right:0;top:50%;transform:translateY(-38%);z-index:150;display:flex;flex-direction:column;align-items:center;width:58px;padding:0 0 0;background:#0A1B25;border-radius:12px 0 0 12px;box-shadow:-10px 14px 34px -12px rgba(0,0,0,.6),inset 3px 0 0 #FD450F;cursor:pointer;color:#fff;transition:width .25s ease}
.qq-tab:hover{width:64px}
.qq-ico{position:absolute;top:-58px;left:46%;width:62px;height:auto;transform:translateX(-50%) rotate(-8deg);filter:drop-shadow(0 6px 10px rgba(0,0,0,.5));animation:qqbob 3.2s ease-in-out infinite}
@keyframes qqbob{0%,100%{transform:translateX(-50%) rotate(-8deg) translateY(0)}50%{transform:translateX(-50%) rotate(-3deg) translateY(-5px)}}
.qq-tab-t{writing-mode:vertical-rl;transform:rotate(180deg);font-family:Poppins,Arial,sans-serif;font-weight:800;font-size:1.02rem;letter-spacing:.14em;text-transform:uppercase;padding:22px 0 18px;white-space:nowrap}
.qq-tab-t b{color:#FF8A5C}
.qq-tab-go{display:grid;place-items:center;width:58px;height:54px;background:#FD450F;color:#0A1B25;border-radius:0 0 0 12px;clip-path:polygon(0 12%,10% 0,22% 12%,34% 0,46% 12%,58% 0,70% 12%,82% 0,94% 12%,100% 0,100% 100%,0 100%)}
.qq-tab-go svg{width:22px;height:22px}
.qq-tog:focus-visible~.qq-tab{outline:3px solid #FD450F;outline-offset:3px}
.qq-veil{position:fixed;inset:0;z-index:290;background:rgba(5,12,17,.62);backdrop-filter:blur(2px);opacity:0;visibility:hidden;transition:opacity .3s ease,visibility .3s}
.qq{position:fixed;top:0;right:0;bottom:0;z-index:300;width:min(540px,100%);overflow-y:auto;background:#0E1A22;color:#fff;border-left:4px solid #FD450F;padding:28px 30px 34px;transform:translateX(105%);visibility:hidden;transition:transform .45s cubic-bezier(.2,.8,.2,1),visibility .45s;box-shadow:-30px 0 80px rgba(0,0,0,.6)}
.qq-tog:checked~.qq{transform:none;visibility:visible}
.qq-tog:checked~.qq-veil{opacity:1;visibility:visible}
.qq-tog:checked~.qq-tab{opacity:0;pointer-events:none}
.qq-x{position:absolute;right:18px;top:18px;width:44px;height:44px;border-radius:50%;display:grid;place-items:center;background:#1B2C37;border:1.5px solid #34505F;cursor:pointer;color:#fff}
.qq-x:hover{background:#FD450F;color:#0A1B25;border-color:#FD450F}.qq-x svg{width:20px;height:20px}
.qq-pill{display:inline-flex;align-items:center;gap:8px;margin:0 0 14px;padding:6px 14px;border-radius:30px;background:#FD450F;color:#0A1B25;font-family:Poppins,Arial,sans-serif;font-weight:800;font-size:.78rem;letter-spacing:.16em;text-transform:uppercase}
.qq-dot{width:8px;height:8px;border-radius:50%;background:#0A1B25;animation:qqblink 1.2s steps(2) infinite}
@keyframes qqblink{50%{opacity:0}}
.qq-title{font-family:Poppins,Arial,sans-serif;font-weight:800;font-size:clamp(1.7rem,4.4vw,2.2rem);line-height:1.05;margin:0 50px 16px 0}
.qq-box{background:linear-gradient(135deg,rgba(253,69,15,.16),rgba(253,69,15,.04));border:1.5px solid rgba(253,69,15,.55);border-left-width:5px;border-radius:10px;padding:14px 16px;margin-bottom:18px}
.qq-box p{margin:0;color:#DCE4E9;font-size:.98rem}.qq-box b{color:#fff}
.qq-form p{margin:0 0 14px}
.qq-row{display:grid;grid-template-columns:1fr 1fr;gap:0 14px}
.qq-form label{display:block;font-family:Poppins,Arial,sans-serif;font-weight:700;font-size:.8rem;letter-spacing:.1em;text-transform:uppercase;margin-bottom:6px;color:#fff}
.qq-form label i{color:#FF8A5C;font-style:normal}.qq-form label span{text-transform:none;letter-spacing:0;font-weight:500;color:#B8C6CF}
.qq-form input[type=text],.qq-form input[type=tel],.qq-form input[type=email],.qq-form textarea{width:100%;min-height:50px;border:1.5px solid #34505F;border-radius:8px;background:#14232D;color:#fff;font:inherit;font-size:1rem;padding:10px 12px}
.qq-form textarea{min-height:104px;resize:vertical}
.qq-form ::placeholder{color:#93A6B2}
.qq-form input:focus-visible,.qq-form textarea:focus-visible{outline:3px solid #FD450F;outline-offset:1px;border-color:#FD450F}
.qq-form input[type=file]{width:100%;border:1.5px dashed #34505F;border-radius:8px;padding:10px;background:#14232D;color:#C9D4DB;font-size:.92rem}
.qq-form input[type=file]::file-selector-button{margin-right:12px;border:0;border-radius:6px;background:#FD450F;color:#0A1B25;font-family:Poppins,Arial,sans-serif;font-weight:800;padding:8px 14px;cursor:pointer}
.qq-go{width:100%;display:flex;align-items:center;justify-content:center;gap:10px;min-height:58px;border:0;border-radius:8px;background:#FD450F;color:#0A1B25;font-family:Poppins,Arial,sans-serif;font-weight:800;font-size:1.1rem;letter-spacing:.06em;text-transform:uppercase;cursor:pointer;box-shadow:0 16px 30px -14px rgba(253,69,15,.9);transition:transform .15s ease}
.qq-go:hover{transform:translateY(-2px)}.qq-go svg{width:20px;height:20px}
.qq-call{display:flex;align-items:center;gap:16px;margin-top:16px;padding:16px 18px;border-radius:10px;background:#14232D;border-left:5px solid #FD450F;color:#fff;text-decoration:none}
