.qq-call-i{flex:none;width:50px;height:50px;border-radius:50%;background:#FD450F;display:grid;place-items:center}.qq-call-i svg{width:24px;height:24px;fill:#0A1B25}
.qq-call small{display:block;font-family:Poppins,Arial,sans-serif;font-weight:700;font-size:.74rem;letter-spacing:.18em;text-transform:uppercase;color:#B8C6CF}
.qq-call b{font-family:Poppins,Arial,sans-serif;font-weight:800;font-size:1.7rem;letter-spacing:-.01em}
.qq-callwrap{margin-top:16px}
.qq-small{margin:14px 0 0;font-size:.86rem;color:#A9BAC5}
@media (max-width:640px){.qq-tab{display:none}.qq{padding:22px 18px 30px}.qq-row{grid-template-columns:1fr}}
@media (prefers-reduced-motion:reduce){.qq,.qq-veil{transition:none}.qq-ico,.qq-dot{animation:none}}

/* ===== one call button, site-wide ===== */
.cbtn{position:relative;display:inline-flex;align-items:center;gap:14px;padding:10px 22px 10px 10px;border-radius:14px;background:linear-gradient(135deg,#FF5A22,#FD450F 55%,#D8380C);color:#0A1B25;text-decoration:none;box-shadow:0 16px 30px -16px rgba(253,69,15,.95);transition:transform .15s ease,box-shadow .2s ease;white-space:nowrap}
.cbtn:hover{transform:translateY(-2px);box-shadow:0 22px 36px -16px rgba(253,69,15,1)}
.cbtn:focus-visible{outline:3px solid #fff;outline-offset:3px;box-shadow:0 0 0 6px #0A1B25}
.cbtn-i{position:relative;flex:none;width:48px;height:48px;border-radius:50%;background:#0A1B25;display:grid;place-items:center}
.cbtn-i svg{width:22px;height:22px;fill:#fff;animation:ringphone 2s ease-in-out infinite;transform-origin:50% 50%}
.cbtn-i i{position:absolute;inset:0;border-radius:50%;border:2px solid #0A1B25;animation:ring 2s ease-out infinite}
.cbtn-i i+i{animation-delay:1s}
.cbtn-t{display:flex;flex-direction:column;line-height:1.05;text-align:left}
.cbtn-t small{font-family:Poppins,Arial,sans-serif;font-weight:700;font-size:.7rem;letter-spacing:.17em;text-transform:uppercase}
.cbtn-t b{font-family:Poppins,Arial,sans-serif;font-weight:800;font-size:1.5rem;letter-spacing:-.01em}
.cbtn-sm{padding:6px 16px 6px 6px;gap:10px;border-radius:12px}
