.mon{position:relative;background:linear-gradient(160deg,#2B3A44,#141C22);border-radius:22px;padding:16px 16px 40px;box-shadow:0 50px 90px -40px rgba(0,0,0,.95),inset 0 1px 0 rgba(255,255,255,.1);transform:perspective(1400px) rotateY(-9deg) rotateX(3deg);transition:transform .8s cubic-bezier(.2,.8,.2,1)}
