.hud b{position:absolute;left:0;right:0;height:40%;top:-40%;background:linear-gradient(180deg,transparent,rgba(124,198,238,.10),transparent);animation:scan 4.5s linear infinite}
@keyframes scan{to{top:100%}}@keyframes blinkrec{50%{opacity:0}}
.sec{padding:clamp(64px,8vw,96px) 0}
.sec h2{font-size:clamp(2rem,3.6vw,3rem);font-weight:800;margin-bottom:16px;max-width:22ch}
.sec .lead{font-size:1.1rem;max-width:46em;color:var(--mut)}
.dark{background:var(--nv);color:#fff}.dark .lead{color:#C9D4DB}
.cream2{background:#fff}
/* X-ray */
.xr{margin-top:30px}
.xr-in{position:absolute;opacity:0;width:1px;height:1px}
.xr-fig{position:relative;border-radius:18px;overflow:hidden;box-shadow:0 0 0 1.5px #1F3D50,0 40px 80px -40px rgba(0,0,0,.9);background:#0C2130}
.xr-svg{display:block;width:100%;height:auto}
.xr-flow{stroke-dasharray:8 16;animation:xflow 1s linear infinite}
@keyframes xflow{to{stroke-dashoffset:-24}}
.xr-block{animation:xpulse 2.2s ease-in-out infinite;transform-box:fill-box;transform-origin:center}
@keyframes xpulse{0%,100%{opacity:.55;transform:scale(.85)}50%{opacity:1;transform:scale(1.15)}}
.xr-mainwater{animation:xpulse 3s ease-in-out infinite;transform-box:fill-box;transform-origin:center}
.hs{position:absolute;transform:translate(-50%,-50%);width:38px;height:38px;border-radius:50%;display:grid;place-items:center;background:#FD450F;color:#0A1B25;font-family:Poppins,Arial,sans-serif;font-weight:800;font-size:1rem;cursor:pointer;box-shadow:0 0 0 4px rgba(10,27,37,.85),0 8px 18px -6px #000;transition:transform .2s ease,background .2s ease}
.hs::after{content:"";position:absolute;inset:-8px;border-radius:50%;border:2px solid #FD450F;animation:ping 2s ease-out infinite;opacity:.8}
.hs:hover{transform:translate(-50%,-50%) scale(1.12)}
.xr-panels{margin-top:18px;background:#fff;color:var(--nv);border-radius:16px;padding:22px 26px;border-left:6px solid #FD450F;min-height:128px}
.xp{display:none}.xp p{margin:0}.xp .xp-t{font-family:Poppins,Arial,sans-serif;font-weight:800;font-size:1.25rem;margin-bottom:6px}
.xp .xp-t small{display:inline-grid;place-items:center;width:28px;height:28px;border-radius:50%;background:var(--nv);color:#fff;font-size:.85rem;margin-right:10px;vertical-align:2px}
.xr-tip{font-size:.95rem;color:#C9D4DB;margin:14px 0 0}
.xr-legend{display:flex;flex-wrap:wrap;gap:8px 10px;margin:14px 0 0;padding:0;list-style:none}
.xr-legend label{display:inline-flex;align-items:center;gap:8px;padding:7px 12px;border-radius:30px;border:1.5px solid #2E5065;font-size:.9rem;font-weight:600;cursor:pointer;color:#DCE4E9}
.xr-legend label b{display:grid;place-items:center;width:22px;height:22px;border-radius:50%;background:#2E5065;color:#fff;font-size:.78rem}
.tblbox{margin-top:46px}
.tblbox h3{font-size:1.35rem;margin-bottom:14px}
.dark .tbl-wrap{background:#fff;color:var(--nv)}
/* drain type cards */
.dcards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22px;margin-top:34px}
.dcard{position:relative;background:#fff;border-radius:18px;padding:28px 28px 26px 104px;box-shadow:0 0 0 1.5px #E6DFD3;transition:box-shadow .3s,transform .3s}
.dcard:hover{transform:translateY(-4px);box-shadow:0 0 0 1.5px #FD450F,0 24px 40px -26px rgba(10,27,37,.5)}
.dcard .di{position:absolute;left:26px;top:26px;width:58px;height:58px;border-radius:16px;background:var(--nv);display:grid;place-items:center}
.dcard .di svg{width:36px;height:36px;fill:none;stroke:#E8EEF2;stroke-width:2.4;stroke-linecap:round;stroke-linejoin:round;overflow:visible}
.dcard h3{font-size:1.3rem;margin-bottom:8px}.dcard p{margin:0;color:var(--mut)}
.uplink{margin:30px 0 0;font-size:1.05rem;max-width:52em}
/* steps pipe */
.runsteps{list-style:none;margin:40px 0 0;padding:0;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:22px;position:relative;counter-reset:st}
.runsteps::before{content:"";position:absolute;left:4%;right:4%;top:27px;height:14px;border-radius:8px;background:linear-gradient(180deg,#D9C7A3,#B49B71);box-shadow:inset 0 -3px 0 rgba(0,0,0,.18)}
.runsteps::after{content:"";position:absolute;left:4%;right:4%;top:32px;height:4px;background:repeating-linear-gradient(90deg,#7CC6EE 0 10px,transparent 10px 24px);animation:sflow 1.2s linear infinite;border-radius:3px}
@keyframes sflow{to{background-position:24px 0}}
.runsteps li{position:relative;z-index:1;counter-increment:st;padding-top:74px}
.runsteps li::before{content:counter(st);position:absolute;top:0;left:0;width:68px;height:68px;border-radius:50%;display:grid;place-items:center;background:var(--nv);color:#fff;font-family:Poppins,Arial,sans-serif;font-weight:800;font-size:1.5rem;box-shadow:0 0 0 6px var(--cream),0 0 0 9px #FD450F}
.runsteps b{display:block;font-family:Poppins,Arial,sans-serif;font-size:1.12rem;margin-bottom:6px}
.runsteps p{margin:0;color:var(--mut);font-size:.98rem}
.methods{display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);gap:clamp(26px,4vw,56px);margin-top:56px;align-items:start}
.methods figure{margin:0;position:sticky;top:130px;border-radius:18px;overflow:hidden;box-shadow:0 30px 60px -36px rgba(10,27,37,.7)}
.mlist{display:grid;gap:18px}
.method{background:#fff;border-radius:16px;padding:24px 26px;box-shadow:0 0 0 1.5px #E6DFD3}
.method h3{font-size:1.3rem;margin-bottom:8px;display:flex;align-items:center;gap:12px}
.method h3::before{content:"";width:12px;height:12px;border-radius:3px;background:#FD450F;transform:rotate(45deg)}
.method p{margin:0;color:var(--mut)}
/* why */
.why3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0;margin-top:40px;border-top:1.5px solid #24465A}
.why3>div{padding:30px 28px 10px 0}
.why3>div+div{padding-left:28px;border-left:1.5px solid #24465A}
.why3 svg{width:100%;max-width:220px;height:86px;margin-bottom:18px}
.why3 h3{font-size:1.3rem;margin-bottom:10px;color:#fff}.why3 p{color:#C9D4DB;margin:0}
.why a.il,.dark a.il{color:#FF8A5C;text-decoration-color:#FF8A5C}
.why a.il:hover,.dark a.il:hover,.why a.il:focus-visible,.dark a.il:focus-visible{color:#fff;text-decoration-color:#fff}
.after{margin-top:26px;max-width:52em}
.tbl.fix td:last-child,.tbl.who td:last-child{color:var(--nv);font-weight:500}
.tbl.who td:nth-child(2){color:#A82C08;font-weight:700}
/* cost */
.cost-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(26px,4vw,64px);align-items:start}
.factors{list-style:none;margin:0;padding:0;display:grid;gap:12px;counter-reset:f}
.factors li{position:relative;background:#fff;border-radius:14px;padding:18px 20px 18px 70px;box-shadow:0 0 0 1.5px #E6DFD3;counter-increment:f}
.factors li::before{content:counter(f);position:absolute;left:18px;top:16px;width:36px;height:36px;border-radius:10px;background:#FD450F;color:#0A1B25;display:grid;place-items:center;font-family:Poppins,Arial,sans-serif;font-weight:800}
.factors b{display:block;font-family:Poppins,Arial,sans-serif;margin-bottom:2px}
.factors span{color:var(--mut);font-size:.98rem}
/* after-care */
.care{display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);gap:clamp(26px,4vw,64px);align-items:start}
.care ul{list-style:none;margin:0;padding:0;display:grid;gap:12px}
.care li{display:flex;gap:14px;align-items:flex-start;background:#fff;border-radius:12px;padding:16px 18px;box-shadow:0 0 0 1.5px #E6DFD3}
.care li::before{content:"";flex:none;width:10px;height:18px;margin:2px 6px 0 4px;border-right:3px solid #FD450F;border-bottom:3px solid #FD450F;transform:rotate(45deg)}
@media (max-width:960px){
 .dh-in{grid-template-columns:1fr}.mon{transform:none;max-width:620px}
 .runsteps{grid-template-columns:1fr 1fr;row-gap:34px}.runsteps::before,.runsteps::after{display:none}
 .methods,.cost-grid,.care{grid-template-columns:1fr}.methods figure{position:relative;top:0;max-width:520px}
 .why3{grid-template-columns:1fr}.why3>div+div{padding-left:0;border-left:0;border-top:1.5px solid #24465A}
}
@media (max-width:640px){
 .dh{padding:30px 0 70px}.dcards{grid-template-columns:1fr}.dcard{padding:24px 22px 22px 90px}.dcard .di{left:20px;width:52px;height:52px}
 .hs{width:28px;height:28px;font-size:.8rem;box-shadow:0 0 0 3px rgba(10,27,37,.85)}.hs::after{inset:-5px}
 .xr-panels{padding:18px 18px}.runsteps{grid-template-columns:1fr}
 .runsteps li{padding:0 0 0 84px;min-height:68px}
}
@media (max-width:600px){
 .tblbox .tbl-wrap{box-shadow:none;background:transparent;overflow:visible}.dark .tblbox .tbl-wrap{background:transparent}
 .tblbox .tbl{min-width:0;display:block}.tblbox .tbl thead{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
 .tblbox .tbl tbody,.tblbox .tbl tr,.tblbox .tbl td{display:block}
 .tblbox .tbl tr{background:#fff;border-radius:14px;box-shadow:0 0 0 1.5px #E6DFD3;margin-bottom:12px;padding:6px 16px}
 .tblbox .tbl tr:nth-child(even) td{background:transparent}
 .tblbox .tbl td{border-top:0;padding:10px 0;border-bottom:1px solid #EFEAE1}.tblbox .tbl td:last-child{border-bottom:0}
 .tblbox .tbl td::before{content:attr(data-label);display:block;font-family:Poppins,Arial,sans-serif;font-size:.74rem;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:#56646E;margin-bottom:3px}
 .tblbox .tbl td:first-child{font-family:Poppins,Arial,sans-serif;font-size:1.02rem}
 .tblbox .tbl caption{display:block;color:#C9D4DB}.cream2 .tblbox .tbl caption,.sec:not(.dark) .tblbox .tbl caption{color:var(--mut)}
}
@media (prefers-reduced-motion:reduce){.xr-flow,.xr-block,.xr-mainwater,.hs::after,.runsteps::after,.hud b,.hud .rec::before{animation:none!important}.xr-cam{display:none}.mon{transform:none}}

/* ===== L01 Marrickville ===== */
.lh{position:relative;background:#0A1B25;color:#fff;overflow:hidden}
.lh-in{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);min-height:620px}
.lh-copy{padding:44px clamp(20px,4vw,56px) 80px max(var(--gut),calc((100vw - var(--wrap))/2 + var(--gut)));position:relative;z-index:2}
.lh .eyebrow{color:#fff}
.lh h1{font-size:clamp(2.3rem,4.4vw,3.8rem);font-weight:800;line-height:1.02;margin-bottom:18px}
.lh h1 em{font-style:normal;color:#FF8A5C;display:block}
.lh-sub{font-size:1.12rem;font-weight:600;margin-bottom:12px}
.lh-lead{color:#C9D4DB;font-size:1.03rem;margin-bottom:26px;max-width:36em}
.lh-lead a.il{color:#FF8A5C;text-decoration-color:#FF8A5C}.lh-lead a.il:hover,.lh-lead a.il:focus-visible{color:#fff;text-decoration-color:#fff}
.lh .hero-cta .textlink{color:#fff;cursor:pointer}
.lh-fig{position:relative;margin:0}
.lh-fig img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.lh-fig::before{content:"";position:absolute;inset:0;z-index:1;background:linear-gradient(90deg,#0A1B25 0%,rgba(10,27,37,0) 22%)}
.stamp{position:absolute;z-index:2;left:-56px;bottom:56px;width:150px;height:150px;border-radius:50%;background:#FD450F;color:#0A1B25;display:grid;place-items:center;text-align:center;transform:rotate(-12deg);box-shadow:0 22px 40px -16px rgba(0,0,0,.8),inset 0 0 0 5px #0A1B25,inset 0 0 0 8px #FD450F,inset 0 0 0 9.5px #0A1B25}
.stamp b{display:block;font-family:Poppins,Arial,sans-serif;font-weight:800;font-size:2.6rem;line-height:1}
.stamp span{display:block;font-family:Poppins,Arial,sans-serif;font-weight:800;font-size:.7rem;letter-spacing:.16em;text-transform:uppercase;margin-top:4px}
.signs6{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin-top:32px;list-style:none;padding:0}
.signs6 li{position:relative;background:#fff;border-radius:16px;padding:22px 22px 22px 86px;box-shadow:0 0 0 1.5px #E6DFD3;min-height:120px}
.signs6 li .si{position:absolute;left:20px;top:22px;width:50px;height:50px;border-radius:50%;background:#FFF1EA;display:grid;place-items:center;box-shadow:inset 0 0 0 2px #FD450F}
.signs6 li .si svg{width:30px;height:30px;fill:none;stroke:#0A1B25;stroke-width:2.4;stroke-linecap:round;stroke-linejoin:round;overflow:visible}
.signs6 b{display:block;font-family:Poppins,Arial,sans-serif;font-size:1.06rem;margin-bottom:4px}
.signs6 p{margin:0;color:var(--mut);font-size:.96rem}
.hist{display:grid;grid-template-columns:minmax(0,.85fr) minmax(0,1.15fr);gap:clamp(28px,5vw,72px);align-items:start}
.hist .terrace{position:static;display:block;width:100%;max-width:460px;margin-top:26px}
.hist-list{display:grid;gap:0;counter-reset:hh}
.hist-list>div{position:relative;padding:26px 0 26px 72px;border-top:1.5px solid #24465A;counter-increment:hh}
.hist-list>div:last-child{border-bottom:1.5px solid #24465A}
.hist-list>div::before{content:counter(hh,decimal-leading-zero);position:absolute;left:0;top:24px;font-family:Poppins,Arial,sans-serif;font-weight:800;font-size:2rem;color:#FD450F;line-height:1}
.hist-list h3{font-size:1.3rem;margin-bottom:8px;color:#fff}.hist-list p{margin:0;color:#C9D4DB}
.jobs{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin-top:30px;list-style:none;padding:0}
.jobs figure{margin:0;position:relative;border-radius:14px;overflow:hidden;box-shadow:0 18px 34px -24px rgba(10,27,37,.7)}
.jobs img{width:100%;aspect-ratio:4/3;object-fit:cover}
.jobs figcaption{position:absolute;left:10px;bottom:10px;padding:6px 12px;border-radius:30px;background:#0A1B25;color:#fff;font-family:Poppins,Arial,sans-serif;font-weight:700;font-size:.82rem}
.cover{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(26px,4vw,56px);align-items:start}
.gmap{position:relative;border-radius:18px;overflow:hidden;box-shadow:0 0 0 1.5px #E6DFD3,0 30px 60px -36px rgba(10,27,37,.7);background:#E9E4DA;aspect-ratio:4/3}
.gmap iframe{position:absolute;inset:0;width:100%;height:100%;border:0}
.nchips{display:flex;flex-wrap:wrap;gap:8px;list-style:none;margin:18px 0;padding:0}
.nchips li{padding:7px 14px;border-radius:30px;background:#fff;box-shadow:0 0 0 1.5px #DED7CB;font-weight:600;font-size:.92rem}
.nchips li:first-child{background:#0A1B25;color:#fff;box-shadow:none}
@media (max-width:1100px){.signs6{grid-template-columns:1fr 1fr}.jobs{grid-template-columns:1fr 1fr}}
@media (max-width:960px){.lh-in{grid-template-columns:1fr}.lh-copy{padding:34px var(--gut) 40px}.lh-fig{min-height:340px}.lh-fig::before{background:linear-gradient(180deg,#0A1B25 0%,rgba(10,27,37,0) 26%)}.stamp{left:auto;right:20px;bottom:20px;width:120px;height:120px}.stamp b{font-size:2.1rem}
 .hist,.cover{grid-template-columns:1fr}}
@media (max-width:640px){.signs6{grid-template-columns:1fr}.jobs{grid-template-columns:1fr 1fr;gap:10px}.jobs figcaption{font-size:.72rem;padding:5px 9px}}

/* ===== page kit additions ===== */
