.checks li::before{content:"";position:absolute;left:20px;top:17px;width:8px;height:15px;border-right:3px solid #FD450F;border-bottom:3px solid #FD450F;transform:rotate(45deg)}
.dark .checks li{background:#12283A;box-shadow:inset 0 0 0 1px #24465A;color:#DCE4E9}
.tabs{margin-top:30px}
