.hp-grid{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,.9fr);gap:clamp(28px,4vw,60px);align-items:center}
.hp-sub{font-size:1.12rem;font-weight:600;margin-bottom:12px}
.hp-lead{color:#C9D4DB;font-size:1.03rem;margin-bottom:24px;max-width:38em}
.hero-plain .hero-cta .textlink{color:#fff;cursor:pointer}
.panel{background:#fff;color:var(--nv);border-radius:18px;padding:24px 26px;box-shadow:0 40px 80px -36px rgba(0,0,0,.9)}
