.cform{background:#fff;border-radius:18px;padding:26px;box-shadow:0 0 0 1.5px #E6DFD3}
.cform label{display:block;font-family:Poppins,Arial,sans-serif;font-weight:700;font-size:.85rem;margin:0 0 6px}
.cform input,.cform textarea,.cform select{width:100%;min-height:50px;border:1.5px solid #B9C2C8;border-radius:8px;padding:10px 12px;font:inherit;margin-bottom:14px;background:#fff;color:#0A1B25}
.cform textarea{min-height:120px}
.cform input:focus-visible,.cform textarea:focus-visible,.cform select:focus-visible{outline:3px solid #FD450F;outline-offset:1px}
.cform .row2{display:grid;grid-template-columns:1fr 1fr;gap:0 12px}
.cform button{width:100%}
.ways{display:grid;gap:14px}
.way{background:#fff;border-radius:16px;padding:20px 22px;box-shadow:0 0 0 1.5px #E6DFD3}
.way b{display:block;font-family:Poppins,Arial,sans-serif;font-size:1.1rem;margin-bottom:4px}
.way p{margin:0 0 10px;color:var(--mut)}.way p:last-child{margin-bottom:0}
.way{min-width:0}.way .btn{white-space:normal;text-align:center;line-height:1.25}
@media (max-width:400px){.way{padding:16px}.way .cbtn{padding:8px 12px 8px 8px;gap:10px}.way .cbtn-t b{font-size:1.2rem}}
.art-grid>*,.contact-grid>*,.hp-grid>*{min-width:0}
.art-fig{margin:0 0 24px;border-radius:18px;overflow:hidden;box-shadow:0 30px 60px -36px rgba(10,27,37,.7)}.art-fig img{width:100%;height:auto}
.panelband{background:#0A1B25;padding:0 0 64px;margin-top:-30px;position:relative}
.panelband .panel{max-width:960px}.panelband .panel ol{columns:2;column-gap:44px}.panelband .panel li{break-inside:avoid}
@media (max-width:760px){.panelband .panel ol{columns:1}}
.sec:not(.dark) .hist-list>div{border-color:#D9D2C6}.sec:not(.dark) .hist-list h3{color:#0A1B25}.sec:not(.dark) .hist-list p{color:#2E3D47}
.tbl.plain td:last-child{color:var(--nv);font-weight:400}
.art .tblbox .tbl caption{color:var(--mut)!important}
.cbtn{max-width:100%}
@media (max-width:960px){.hp-grid,.art-grid,.contact-grid{grid-template-columns:1fr}.art-side{position:static}}
@media (max-width:520px){.cform .row2{grid-template-columns:1fr}}

.hub-hero .hp-grid{align-items:center}
.hubmap.map{margin:0;border-radius:18px;overflow:hidden;box-shadow:0 40px 80px -36px rgba(0,0,0,.9)}
.hubmap svg{display:block;width:100%;height:auto;aspect-ratio:1/1}
.councils{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px;margin-top:28px}
.council{background:#fff;border-radius:16px;padding:22px 24px;box-shadow:0 0 0 1.5px #E6DFD3;border-top:5px solid #FD450F}
.council h3{font-size:1.2rem;margin:0 0 12px}
.council ul{list-style:none;margin:0;padding:0;display:grid;gap:8px}
.council li{display:flex;flex-wrap:wrap;align-items:baseline;gap:4px 10px}
.council li a{font-family:Poppins,Arial,sans-serif;font-weight:700;color:#0A1B25;text-decoration:underline;text-decoration-color:#FD450F;text-underline-offset:3px}
.council li a:hover{color:#A82C08}
.council .pc{font-size:.85rem;font-weight:700;color:#A82C08}
.council .nt{color:var(--mut);font-size:.95rem}
.svcs{list-style:none;margin:26px 0 0;padding:0;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}
.svcs li{background:#fff;border-radius:14px;padding:16px 18px;box-shadow:0 0 0 1.5px #E6DFD3}
.svcs a{font-family:Poppins,Arial,sans-serif;font-weight:700;color:#0A1B25;text-decoration:underline;text-decoration-color:#FD450F;text-underline-offset:3px}
.svcs a:hover{color:#A82C08}
.svcs p{margin:6px 0 0;color:var(--mut);font-size:.95rem}
@media (max-width:900px){.councils,.svcs{grid-template-columns:1fr}}
@media (min-width:620px) and (max-width:900px){.svcs{grid-template-columns:1fr 1fr}}
